using System.ComponentModel.DataAnnotations;
using System.ComponentModel.DataAnnotations.Schema;
using SMS.Generic.Common.Audit;

namespace SMS.Generic.Entities.Entities
{
    /// <summary>
    /// Represents an employee status entity in the system.
    /// </summary>
    [AuditedEntity(DisplayPropertyName = nameof(StatusShort), OnlyAttributedProperties = true)]
    [Table("EmployeeStatus", Schema = "dbo")]
    public class EmployeeStatus : BaseEntity
    {
        /// <summary>
        /// Primary Key (GUID) - Auto-generated by database using NEWID()
        /// </summary>
        [Key]
        [DatabaseGenerated(DatabaseGeneratedOption.Identity)]
        public Guid EmployeeStatusID { get; set; }

        /// <summary>
        /// FK → Department.DepartmentID
        /// </summary>
        [Required]
        [AuditedProperty("Department", LookupEntityType = typeof(Department), LookupDisplayPropertyName = nameof(Department.DepartmentName))]
        public Guid DepartmentID { get; set; }

        /// <summary>
        /// Short label for employee status.
        /// </summary>
        [MaxLength(100)]
        [AuditedProperty("Title")]
        public string? StatusShort { get; set; }

        /// <summary>
        /// Long description for employee status.
        /// </summary>
        [MaxLength(255)]
        [AuditedProperty("Description")]
        public string? StatusLong { get; set; }

        /// <summary>
        /// Status 
        /// </summary>
        [AuditedProperty("Active")]
        public bool? Status { get; set; }


        /// <summary>
        /// Navigation property for the department.
        /// </summary>
        [ForeignKey("DepartmentID")]
        public virtual Department? Department { get; set; }

        /// <summary>
        /// Navigation property for the employee who created this employee status.
        /// </summary>
        [ForeignKey("CreatedUserID")]
        public virtual Employee? CreatedByEmployee { get; set; }

        /// <summary>
        /// Navigation property for the employee who last edited this employee status.
        /// </summary>
        [ForeignKey("EditedUserID")]
        public virtual Employee? EditedByEmployee { get; set; }
    }
}

